-- Migration 032: Third-party SOC alerts.
--
-- Stores analyst-reviewable third-party alerts generated by the
-- continuous monitoring layer. Each alert links a threat/change to a
-- customer-vendor relationship with business-specific risk context.
--
-- Purely additive. No existing columns modified.

CREATE TABLE IF NOT EXISTS third_party_alerts (
    id SERIAL PRIMARY KEY,
    customer_id INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
    customer_vendor_id INTEGER NOT NULL REFERENCES customer_vendors(id) ON DELETE CASCADE,
    profile_id INTEGER REFERENCES third_party_profiles(id) ON DELETE SET NULL,
    threat_event_id INTEGER REFERENCES threat_events(id) ON DELETE SET NULL,
    exposure_id INTEGER REFERENCES third_party_exposures(id) ON DELETE SET NULL,
    architecture_change_id INTEGER REFERENCES architecture_changes(id) ON DELETE SET NULL,
    vendor VARCHAR(255) NOT NULL,
    affected_technology VARCHAR(255),
    alert_type VARCHAR(40) NOT NULL,  -- VULNERABILITY, BREACH, RANSOMWARE, SECURITY_INCIDENT, ATTACK_TECHNIQUE, ARCHITECTURE_CHANGE, EXTERNAL_EXPOSURE, OTHER
    severity VARCHAR(20) NOT NULL DEFAULT 'MEDIUM',
    risk_score INTEGER NOT NULL DEFAULT 0,      -- 0-100 customer-specific
    risk_delta INTEGER NOT NULL DEFAULT 0,      -- change from prior baseline
    confidence DOUBLE PRECISION NOT NULL DEFAULT 0.5,
    confidence_reasons JSONB DEFAULT '[]'::jsonb,
    evidence JSONB DEFAULT '[]'::jsonb,
    business_relevance TEXT,
    recommended_action TEXT,
    status VARCHAR(20) NOT NULL DEFAULT 'NEW',  -- NEW, ACKNOWLEDGED, RESOLVED, DISMISSED
    source_type VARCHAR(30),                    -- exposure, architecture_change, manual
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_tp_alerts_customer ON third_party_alerts (customer_id);
CREATE INDEX IF NOT EXISTS idx_tp_alerts_vendor ON third_party_alerts (customer_vendor_id);
CREATE INDEX IF NOT EXISTS idx_tp_alerts_type ON third_party_alerts (alert_type);
CREATE INDEX IF NOT EXISTS idx_tp_alerts_severity ON third_party_alerts (severity);
CREATE INDEX IF NOT EXISTS idx_tp_alerts_created ON third_party_alerts (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tp_alerts_status ON third_party_alerts (status);
CREATE INDEX IF NOT EXISTS idx_tp_alerts_threat ON third_party_alerts (threat_event_id);

COMMENT ON TABLE third_party_alerts IS 'Analyst-reviewable third-party alerts generated by the continuous monitoring layer';
COMMENT ON COLUMN third_party_alerts.alert_type IS 'VULNERABILITY, BREACH, RANSOMWARE, SECURITY_INCIDENT, ATTACK_TECHNIQUE, ARCHITECTURE_CHANGE, EXTERNAL_EXPOSURE, OTHER';
COMMENT ON COLUMN third_party_alerts.risk_score IS 'Customer-specific risk score (0-100) combining threat severity + business context';
COMMENT ON COLUMN third_party_alerts.business_relevance IS 'Human-readable description of why this threat matters for this customer';
COMMENT ON COLUMN third_party_alerts.recommended_action IS 'Explainable SOC action derived from actual evidence';